{
  "name": "SAMI AI Fintech Chatbot",
  "description": "An AI-powered chatbot for the SAMI platform, designed to assist micro and small enterprises in Peru with accounting, micro-loans, and business education, powered by the Gemini API."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useRef, useCallback } from 'react';
import type { Message } from './types';
import { Sender } from './types';
import ChatWindow from './components/ChatWindow';
import { sendMessageToGemini } from './services/geminiService';
import type { Chat } from '@google/genai';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const chatRef = useRef<Chat | null>(null);

  useEffect(() => {
    setMessages([
      {
        id: 'initial',
        text: '¡Hola! Soy SAMI, tu asistente de IA. Estoy aquí para ayudarte con tus consultas sobre contabilidad, microcréditos y educación empresarial para MYPES en Perú. ¿En qué puedo ayudarte hoy?',
        sender: Sender.BOT,
      },
    ]);
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text,
      sender: Sender.USER,
    };

    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setIsLoading(true);
    setError(null);

    try {
      const { chat, response } = await sendMessageToGemini(text, chatRef.current);
      chatRef.current = chat; // Update the chat session reference

      const botMessage: Message = {
        id: Date.now().toString() + '-bot',
        text: response,
        sender: Sender.BOT,
      };
      setMessages((prevMessages) => [...prevMessages, botMessage]);
    } catch (err) {
      const errorMessage = 'Lo siento, ocurrió un error al procesar tu solicitud. Por favor, inténtalo de nuevo más tarde.';
      setError(errorMessage);
      const errorBotMessage: Message = {
        id: Date.now().toString() + '-error',
        text: errorMessage,
        sender: Sender.BOT,
      };
      setMessages((prevMessages) => [...prevMessages, errorBotMessage]);
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, []);

  return (
    <div className="bg-gray-100 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 w-full h-screen flex flex-col items-center justify-center">
      <ChatWindow
        messages={messages}
        isLoading={isLoading}
        onSendMessage={handleSendMessage}
        error={error}
      />
    </div>
  );
};

export default App;

export enum Sender {
  USER = 'user',
  BOT = 'bot',
}

export interface Message {
  id: string;
  text: string;
  sender: Sender;
}

import { GoogleGenAI, Chat, GenerateContentResponse } from "@google/genai";

const SYSTEM_INSTRUCTION = `Actúas como 'SAMI', un asistente experto de IA para la plataforma SAMI. Te especializas en contabilidad peruana, microcréditos para MYPES (Micro y Pequeñas Empresas) y educación empresarial. Tu tono debe ser profesional, servicial y alentador. Responde a las preguntas en el contexto de ayudar a un dueño de una pequeña empresa en Perú. Utiliza un lenguaje claro y evita la jerga compleja a menos que la expliques. Formatea tus respuestas con markdown cuando sea apropiado para una mejor legibilidad (listas, negritas, etc.).`;

const getApiKey = (): string => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API_KEY environment variable not set.");
  }
  return apiKey;
};

export const sendMessageToGemini = async (message: string, existingChat: Chat | null) => {
  const ai = new GoogleGenAI({ apiKey: getApiKey() });

  const chat = existingChat || ai.chats.create({
    model: 'gemini-3-pro-preview',
    config: {
      systemInstruction: SYSTEM_INSTRUCTION,
    },
  });

  const result: GenerateContentResponse = await chat.sendMessage({ message });
  const responseText = result.text;

  if (!responseText) {
    throw new Error("No response text received from Gemini.");
  }

  return { chat, response: responseText };
};

import React from 'react';
import type { Message } from '../types';
import MessageList from './MessageList';
import ChatInput from './ChatInput';

interface ChatWindowProps {
  messages: Message[];
  isLoading: boolean;
  onSendMessage: (text: string) => void;
  error: string | null;
}

const ChatWindow: React.FC<ChatWindowProps> = ({ messages, isLoading, onSendMessage, error }) => {
  return (
    <div className="flex flex-col h-full md:h-[90vh] w-full max-w-3xl bg-white dark:bg-gray-800 shadow-2xl rounded-lg overflow-hidden">
      <header className="bg-blue-600 dark:bg-blue-800 p-4 text-white flex items-center shadow-md">
        <div className="w-10 h-10 bg-white rounded-full flex items-center justify-center mr-3">
          <svg className="w-6 h-6 text-blue-600 dark:text-blue-800" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a2 2 0 01-2-2V4a2 2 0 012-2h8a2 2 0 012 2v4z"></path></svg>
        </div>
        <div>
          <h1 className="text-xl font-bold">Asistente SAMI</h1>
          <p className="text-sm opacity-90">Tu copiloto financiero y contable</p>
        </div>
      </header>
      <MessageList messages={messages} isLoading={isLoading} />
      <ChatInput onSendMessage={onSendMessage} isLoading={isLoading} />
      {error && <div className="p-2 text-center text-red-500 bg-red-100 dark:bg-red-900 text-sm">{error}</div>}
    </div>
  );
};

export default ChatWindow;

import React, { useRef, useEffect } from 'react';
import type { Message } from '../types';
import { Sender } from '../types';
import MessageBubble from './MessageBubble';

interface MessageListProps {
  messages: Message[];
  isLoading: boolean;
}

const TypingIndicator: React.FC = () => (
  <div className="flex justify-start p-3">
    <div className="flex items-center space-x-2">
      <div className="w-10 h-10 bg-blue-500 rounded-full flex items-center justify-center text-white font-bold text-xl">S</div>
      <div className="bg-gray-200 dark:bg-gray-700 rounded-lg p-3 flex items-center space-x-1">
        <span className="typing-dot animate-bounce w-2 h-2 bg-gray-500 rounded-full"></span>
        <span className="typing-dot animate-bounce delay-150 w-2 h-2 bg-gray-500 rounded-full" style={{animationDelay: '0.2s'}}></span>
        <span className="typing-dot animate-bounce delay-300 w-2 h-2 bg-gray-500 rounded-full" style={{animationDelay: '0.4s'}}></span>
      </div>
    </div>
  </div>
);

const MessageList: React.FC<MessageListProps> = ({ messages, isLoading }) => {
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isLoading]);

  return (
    <div className="flex-1 p-4 overflow-y-auto bg-gray-50 dark:bg-gray-900">
      {messages.map((message) => (
        <MessageBubble key={message.id} message={message} />
      ))}
      {isLoading && <TypingIndicator />}
      <div ref={messagesEndRef} />
    </div>
  );
};

export default MessageList;

import React from 'react';
import type { Message } from '../types';
import { Sender } from '../types';

interface MessageBubbleProps {
  message: Message;
}

const BotAvatar: React.FC = () => (
  <div className="w-10 h-10 bg-blue-500 rounded-full flex items-center justify-center text-white font-bold text-xl flex-shrink-0">
    S
  </div>
);

const UserAvatar: React.FC = () => (
    <div className="w-10 h-10 bg-gray-300 dark:bg-gray-600 rounded-full flex items-center justify-center text-gray-600 dark:text-gray-300 flex-shrink-0">
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z"></path></svg>
    </div>
);


const MessageBubble: React.FC<MessageBubbleProps> = ({ message }) => {
  const isBot = message.sender === Sender.BOT;

  const bubbleClasses = isBot
    ? 'bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200'
    : 'bg-blue-500 dark:bg-blue-700 text-white';

  const containerClasses = `flex items-start gap-3 my-4 ${isBot ? 'justify-start' : 'justify-end'}`;

  const textContentWithBreaks = message.text.split('\n').map((line, index) => (
    <React.Fragment key={index}>
      {line}
      <br />
    </React.Fragment>
  ));

  return (
    <div className={containerClasses}>
      {isBot && <BotAvatar />}
      <div className={`max-w-md md:max-w-lg p-3 rounded-lg shadow ${bubbleClasses}`}>
        <p className="text-sm prose dark:prose-invert max-w-none">{textContentWithBreaks}</p>
      </div>
      {!isBot && <UserAvatar />}
    </div>
  );
};

export default MessageBubble;

import React, { useState } from 'react';

interface ChatInputProps {
  onSendMessage: (text: string) => void;
  isLoading: boolean;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading }) => {
  const [text, setText] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() && !isLoading) {
      onSendMessage(text);
      setText('');
    }
  };

  return (
    <div className="p-4 bg-white dark:bg-gray-800 border-t border-gray-200 dark:border-gray-700">
      <form onSubmit={handleSubmit} className="flex items-center space-x-3">
        <input
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Escribe tu consulta aquí..."
          className="flex-1 p-3 border border-gray-300 dark:border-gray-600 rounded-full focus:outline-none focus:ring-2 focus:ring-blue-500 bg-gray-100 dark:bg-gray-700 text-gray-900 dark:text-gray-200"
          disabled={isLoading}
        />
        <button
          type="submit"
          disabled={isLoading || !text.trim()}
          className="bg-blue-500 text-white p-3 rounded-full hover:bg-blue-600 disabled:bg-blue-300 dark:disabled:bg-blue-800 disabled:cursor-not-allowed focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800 transition-colors duration-200 flex-shrink-0"
        >
          {isLoading ? (
            <svg className="animate-spin h-6 w-6 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
          ) : (
             <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg>
          )}
        </button>
      </form>
    </div>
  );
};

export default ChatInput;

