import { useRef, useEffect } from 'react';
import type { Message, Sender } from './types';
import { useGemini } from './geminiService';
import { DEFAULT_SYSTEM_INSTRUCTION } from './constants';
import ChatInput from './components/ChatInput';
import MessageList from './components/MessageList';
import { useLocalStorage } from './hooks/useLocalStorage';
import { formatMessages } from './utils';

function App() {
  const { messages, loading, sendMessage, clearMessages } = useGemini();
  const [currentView, setCurrentView] = React.useState<'chat' | 'accounting'>('chat');

  const [storedMessages, setStoredMessages] = useLocalStorage<Message[]>('messages', []);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async (text: string) => {
    if (!text.trim()) return;

    setStoredMessages((prevMessages) => [...prevMessages, { id: crypto.randomUUID(), text, sender: Sender.USER }]);
    await sendMessage(text);
  };

  useEffect(() => {
    if (storedMessages.length > 0) {
      const formattedMessages = formatMessages(storedMessages, DEFAULT_SYSTEM_INSTRUCTION);
      sendMessage(formattedMessages);
    }
  }, [storedMessages, sendMessage]);

  const handleClearChat = () => {
    clearMessages();
    setStoredMessages([]);
  };

  return (
    <div className="bg-gray-100 dark:bg-gray-900 min-h-screen py-6 px-4 sm:px-6 lg:px-8">
      {/* Header */}
      <header className="mb-4">
        <h1 className="text-3xl font-bold text-gray-800 dark:text-white">SAMI - Chatbot & Accounting</h1>
        <p className="text-gray-600 dark:text-gray-400">Your AI-powered assistant for conversation and accounting needs.</p>
      </header>
      <div className="flex flex-col h-full bg-white dark:bg-gray-800 shadow-md rounded-lg overflow-hidden">
        {/* Navigation */}
        <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-gray-700">
          <div>
            <button
              onClick={() => setCurrentView('chat')}
              className={`px-4 py-2 rounded-md ${currentView === 'chat'
                ? 'bg-blue-500 text-white'
                : 'hover:bg-gray-100 dark:hover:bg-gray-700'
                }`}
            >
              Chat
            </button>
            <button
              onClick={() => setCurrentView('accounting')}
              className={`ml-2 px-4 py-2 rounded-md ${currentView === 'accounting'
                ? 'bg-blue-500 text-white'
                : 'hover:bg-gray-100 dark:hover:bg-gray-700'
                }`}
            >
              Accounting
            </button>
          </div>
          {currentView === 'chat' && (
            <button
              onClick={handleClearChat}
              className="px-4 py-2 rounded-md text-red-500 hover:bg-red-100 dark:hover:bg-red-800"
            >
              Clear Chat
            </button>
          )}
        </div>
        {/* Content */}
        {currentView === 'chat' ? (
          <div className="flex flex-col h-full overflow-hidden">
            <MessageList messages={messages} loading={loading} />
            <div ref={messagesEndRef} />
            <ChatInput onSendMessage={handleSendMessage} disabled={loading} />
          </div>
        ) : (
          <div className="p-4">
            {/* Replace with your AccountingModule Component */}
            {/* <AccountingModule /> */}
          </div>
        )}
      </div>
    </div>
  );
}

**Refactoring Accounting Integration**

I'm now integrating the `AccountingModule.tsx` within the application, and the necessary backend services. My focus is structuring the UI with tabs for sales and purchases and utilizing `useState` to maintain invoice data. I will include validation and use the service for tax calculation within the component, allowing a cleaner presentation of data.

