/**
 * Calculates a "SAMI Score" based on sales history.
 * @param salesHistory Array of sales invoices.
 * @returns A SamiScoreResult object or null if data is insufficient.
 */
export const calculateSamiScore = (salesHistory: Invoice[]): SamiScoreResult | null => {
    // Need at least 3 months of data for a meaningful analysis
    if (salesHistory.length < 5) return null;

    // 1. Group sales by month
    const monthlySales: { [key: string]: number } = {};
    salesHistory.forEach(inv => {
        const month = inv.issueDate.substring(0, 7); // YYYY-MM
        if (!monthlySales[month]) monthlySales[month] = 0;
        monthlySales[month] += inv.totalAmount;
    });

    const months = Object.keys(monthlySales).sort();
    if (months.length < 3) return null; // Ensure we have at least 3 distinct months

    const monthlyTotals = months.map(m => monthlySales[m]);

    // 2. Calculate Metrics
    const totalSales = monthlyTotals.reduce((a, b) => a + b, 0);
    const avgMonthlySales = totalSales / monthlyTotals.length;

    // Stability Score (based on Coefficient of Variation, inverted and scaled)
    const mean = avgMonthlySales;
    const stdDev = Math.sqrt(monthlyTotals.map(x => Math.pow(x - mean, 2)).reduce((a, b) => a + b) / monthlyTotals.length);
    const coeffOfVariation = mean > 0 ? stdDev / mean : 1;
    const stabilityScore = Math.max(0, 100 * (1 - coeffOfVariation));

    // Growth Score (based on simple linear regression slope, scaled)
    let slope = 0;
    if (monthlyTotals.length > 1) {
        let sumX = 0, sumY = 0, sumXY = 0, sumX2 = 0;
        monthlyTotals.forEach((y, i) => {
            sumX += i;
            sumY += y;
            sumXY += i * y;
            sumX2 += i * i;
        });
        const n = monthlyTotals.length;
        slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
    }
    const normalizedSlope = mean > 0 ? slope / mean : 0;
    const growthScore = Math.max(0, Math.min(100, 50 + normalizedSlope * 200)); // Scaled

    // Formality Score (percentage of sales made with Factura)
    const facturasCount = salesHistory.filter(inv => inv.documentType === DocumentType.FACTURA).length;
    const formalityScore = (facturasCount / salesHistory.length) * 100;

    // 3. Combine into SAMI Score
    // Weights: Stability 45%, Growth 35%, Formality 20%
    const weightedScore = (stabilityScore * 0.45) + (growthScore * 0.35) + (formalityScore * 0.20);
    const samiScore = 300 + (weightedScore * 5.5); // Scale to 300-850 range

    let tier: SamiScoreResult['tier'] = 'Necesita Mejora';
    if (samiScore > 720) tier = 'Excelente';
    else if (samiScore > 650) tier = 'Bueno';
    else if (samiScore > 550) tier = 'Regular';

    return {
        score: Math.round(samiScore),
        tier,
        analysis: {
            stability: Math.round(stabilityScore),
            growth: Math.round(growthScore),
            formality: Math.round(formalityScore),
        },
        avgMonthlySales: Math.round(avgMonthlySales),
    };
};


/**
 * Generates simulated loan offers based on the SAMI Score.
 * @param scoreResult The result from calculateSamiScore.
 * @returns An array of LoanOffer objects.
 */
export const generateLoanOffers = (scoreResult: SamiScoreResult): LoanOffer[] => {
    const { score, avgMonthlySales } = scoreResult;
    const offers: LoanOffer[] = [];

    // Partner A: Fintech Veloz (higher risk, higher rate)
    if (score > 580) {
        offers.push({
            partner: mockPartners[0],
            maxAmount: Math.min(30000, avgMonthlySales * 1.5),
            monthlyInterestRate: 0.05, // 5%
            termInMonths: 12,
        });
    }

    // Partner B: Caja Confianza (medium risk, medium rate)
    if (score > 620) {
        offers.push({
            partner: mockPartners[1],
            maxAmount: Math.min(50000, avgMonthlySales * 1.2),
            monthlyInterestRate: 0.035, // 3.5%
            termInMonths: 24,
        });
    }

    // Partner C: Banco ProMYPE (low risk, low rate)
    if (score > 700) {
        offers.push({
            partner: mockPartners[2],
            maxAmount: Math.min(80000, avgMonthlySales * 2.0),
            monthlyInterestRate: 0.022, // 2.2%
            termInMonths: 36,
        });
    }

    // Ensure at least one "starter" offer for scores that are regular but not great
    if (score > 550 && offers.length === 0) {
         offers.push({
            partner: mockPartners[0],
            maxAmount: Math.min(10000, avgMonthlySales * 0.8),
            monthlyInterestRate: 0.065, // 6.5%
            termInMonths: 6,
        });
    }


    return offers.map(offer => ({
        ...offer,
        maxAmount: Math.floor(offer.maxAmount / 100) * 100, // Round down to nearest 100
    })).sort((a,b) => b.maxAmount - a.maxAmount);
};

import React, { useState } from 'react';
import type { Invoice, SamiScoreResult, LoanOffer } from '../types';
import { calculateSamiScore, generateLoanOffers } from '../services/creditService';
import SamiScoreGauge from './SamiScoreGauge';
import LoanOfferCard from './LoanOfferCard';

interface CreditMarketplaceProps {
  salesHistory: Invoice[];
}

const CreditMarketplace: React.FC<CreditMarketplaceProps> = ({ salesHistory }) => {
  const [scoreResult, setScoreResult] = useState<SamiScoreResult | null>(null);
  const [loanOffers, setLoanOffers] = useState<LoanOffer[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleEvaluateCredit = () => {
    setIsLoading(true);
    setError(null);
    setScoreResult(null);
    setLoanOffers([]);

    // Simulate async operation
    setTimeout(() => {
      try {
        const result = calculateSamiScore(salesHistory);
        if (result) {
          setScoreResult(result);
          const offers = generateLoanOffers(result);
          setLoanOffers(offers);
        } else {
          setError("No hay suficientes datos para una evaluación. Se recomienda registrar ventas de al menos 3 meses distintos.");
        }
      } catch (err: any) {
        setError("Ocurrió un error inesperado al calcular el score.");
        console.error(err);
      } finally {
        setIsLoading(false);
      }
    }, 1000);
  };

  return (
    <div className="container mx-auto p-4 max-w-7xl h-full flex flex-col gap-6">
      <header>
        <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Marketplace de Créditos</h1>
        <p className="text-gray-600 dark:text-gray-400">Pre-evalúa tu negocio para acceder a ofertas de crédito de nuestros aliados.</p>
      </header>

      <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-md text-center">
        <h2 className="text-xl font-semibold mb-4">¿Listo para crecer?</h2>
        <p className="text-gray-600 dark:text-gray-400 mb-6 max-w-2xl mx-auto">
          Usa tu historial de ventas registrado en SAMI para obtener un score crediticio y ver ofertas simuladas de capital de trabajo.
          Mientras más ventas registres, ¡mejores serán tus oportunidades!
        </p>
        <button
          onClick={handleEvaluateCredit}
          disabled={isLoading}
          className="bg-blue-600 text-white font-bold py-3 px-8 rounded-full hover:bg-blue-700 disabled:bg-blue-400 transition-transform transform hover:scale-105 disabled:cursor-not-allowed"
        >
          {isLoading ? 'Evaluando...' : '¡Pre-evaluar mi Crédito Ahora!'}
        </button>
      </div>

      {isLoading && (
        <div className="text-center p-8">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
            <p className="mt-4 text-gray-600 dark:text-gray-400">Analizando tu historial de ventas...</p>
        </div>
      )}

      {error && (
        <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-md" role="alert">
            <p className="font-bold">Error de Evaluación</p>
            <p>{error}</p>
        </div>
      )}

      {scoreResult && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
            <div className="lg:col-span-1">
                <SamiScoreGauge scoreResult={scoreResult} />
            </div>
            <div className="lg:col-span-2">
                <h3 className="text-2xl font-bold mb-4 text-gray-800 dark:text-white">Ofertas de Crédito Simuladas</h3>
                {loanOffers.length > 0 ? (
                    <div className="space-y-4">
                        {loanOffers.map((offer, index) => (
                            <LoanOfferCard key={index} offer={offer} />
                        ))}
                    </div>
                ) : (
                    <div className="bg-yellow-50 dark:bg-gray-700 p-6 rounded-lg text-center">
                        <h4 className="font-semibold text-yellow-800 dark:text-yellow-300">Aún no hay ofertas disponibles</h4>
                        <p className="text-sm text-yellow-700 dark:text-yellow-400 mt-2">
                            Según tu score actual, no hemos encontrado ofertas. ¡Sigue registrando tus ventas para mejorar tu puntaje y acceder a financiamiento!
                        </p>
                    </div>
                )}
            </div>
        </div>
      )}
