import React from 'react';
import type { SamiScoreResult } from '../types';

interface SamiScoreGaugeProps {
  scoreResult: SamiScoreResult;
}

const SamiScoreGauge: React.FC<SamiScoreGaugeProps> = ({ scoreResult }) => {
  const { score, tier, analysis, avgMonthlySales } = scoreResult;
  const scorePercentage = (score - 300) / (850 - 300);
  const rotation = -90 + (scorePercentage * 180);

  const getTierColor = () => {
    switch(tier) {
      case 'Excelente': return 'text-green-500';
      case 'Bueno': return 'text-blue-500';
      case 'Regular': return 'text-yellow-500';
      case 'Necesita Mejora': return 'text-red-500';
      default: return 'text-gray-500';
    }
  };

  const getProgressBarBg = (value: number) => {
      if (value > 75) return 'bg-green-500';
      if (value > 50) return 'bg-blue-500';
      if (value > 25) return 'bg-yellow-500';
      return 'bg-red-500';
  }

  return (
    <div className="bg-white dark:bg-gray-800 p-6 rounded-lg shadow-md text-center sticky top-6">
      <h3 className="text-lg font-semibold text-gray-700 dark:text-gray-200 mb-2">Tu SAMI Score</h3>

      <div className="relative w-48 h-24 mx-auto mb-2 overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full border-t-0 border-8 border-gray-200 dark:border-gray-600 rounded-t-full" style={{ clipPath: 'inset(0 0 0 0)'}}></div>
        <div className={`absolute top-0 left-0 w-full h-full border-t-0 border-8 rounded-t-full transition-transform duration-1000 ${getTierColor().replace('text-', 'border-')}`} style={{ transform: `rotate(${rotation}deg)`}}></div>
      </div>

      <div className="text-5xl font-bold" style={{ marginTop: '-2.5rem' }}>
        <span className={getTierColor()}>{score}</span>
      </div>
      <p className={`font-semibold text-xl ${getTierColor()}`}>{tier}</p>
      <p className="text-sm text-gray-500 dark:text-gray-400">Venta Mensual Prom.: S/ {avgMonthlySales.toLocaleString('es-PE')}</p>

      <div className="mt-6 text-left space-y-3">
        <h4 className="font-semibold text-md text-gray-800 dark:text-gray-200 border-b pb-2 dark:border-gray-600">Análisis Detallado</h4>
        <div>
            <div className="flex justify-between mb-1 text-sm font-medium text-gray-600 dark:text-gray-300">
                <span>Estabilidad</span>
                <span>{analysis.stability}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                <div className={`${getProgressBarBg(analysis.stability)} h-2.5 rounded-full`} style={{ width: `${analysis.stability}%` }}></div>
            </div>
        </div>
        <div>
            <div className="flex justify-between mb-1 text-sm font-medium text-gray-600 dark:text-gray-300">
                <span>Crecimiento</span>
                <span>{analysis.growth}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                <div className={`${getProgressBarBg(analysis.growth)} h-2.5 rounded-full`} style={{ width: `${analysis.growth}%` }}></div>
            </div>
        </div>
        <div>
            <div className="flex justify-between mb-1 text-sm font-medium text-gray-600 dark:text-gray-300">
                <span>Formalidad</span>
                <span>{analysis.formality}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5 dark:bg-gray-700">
                <div className={`${getProgressBarBg(analysis.formality)} h-2.5 rounded-full`} style={{ width: `${analysis.formality}%` }}></div>
            </div>
        </div>
      </div>
    </div>
  );
};

