import React, { useState, useEffect, useRef, useCallback } from 'react';
import type { Message, Invoice } from './types';
import { Sender, InvoiceType, DocumentType } from './types';
import ChatWindow from './components/ChatWindow';
import AccountingModule from './components/AccountingModule';
import CreditMarketplace from './components/CreditMarketplace';
import EducationModule from './components/EducationModule';
import { sendMessageToGemini } from './services/geminiService';
import { calculateTaxes } from './services/accountingService';
import type { Chat } from '@google/genai';

type View = 'chat' | 'accounting' | 'credit' | 'education';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<View>('accounting');

  // Chatbot State
  const [messages, setMessages] = useState<Message[]>([]);
  const [isChatLoading, setIsChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);
  const chatRef = useRef<Chat | null>(null);

  // Accounting & Credit State (State lifted up)
  const [sales, setSales] = useState<Invoice[]>([]);
  const [purchases, setPurchases] = useState<Invoice[]>([]);

  const handleAddInvoice = (invoice: Omit<Invoice, 'id'>) => {
      // Pre-validation before adding. The service throws an error on failure.
      calculateTaxes([], [ { ...invoice, id: 'temp' } ]); 

      const newInvoice: Invoice = {
        ...invoice,
        id: crypto.randomUUID(),
      };

      if (invoice.type === InvoiceType.SALE) {
          setSales(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      } else {
          setPurchases(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      }
  };


  useEffect(() => {
    setMessages([
      {
        id: 'initial',
        text: '¡Hola! Soy SAMI, tu asistente de IA. Estoy aquí para ayudarte con tus consultas sobre contabilidad, microcréditos y educación empresarial para MYPES en Perú. ¿En qué puedo ayudarte hoy?',
        sender: Sender.BOT,
      },
    ]);
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text,
      sender: Sender.USER,
    };

    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setIsChatLoading(true);
    setChatError(null);

    try {
      const { chat, response } = await sendMessageToGemini(text, chatRef.current);
      chatRef.current = chat; // Update the chat session reference

      const botMessage: Message = {
        id: Date.now().toString() + '-bot',
        text: response,
        sender: Sender.BOT,
      };
      setMessages((prevMessages) => [...prevMessages, botMessage]);
    } catch (err) {
      const errorMessage = 'Lo siento, ocurrió un error al procesar tu solicitud. Por favor, inténtalo de nuevo más tarde.';
      setChatError(errorMessage);
      const errorBotMessage: Message = {
        id: Date.now().toString() + '-error',
        text: errorMessage,
        sender: Sender.BOT,
      };
      setMessages((prevMessages) => [...prevMessages, errorBotMessage]);
      console.error(err);
    } finally {
      setIsChatLoading(false);
    }
  }, []);

  const navButtonClasses = (view: View) => 
    `px-4 py-2 text-sm font-medium rounded-md transition-colors ${
      currentView === view 
        ? 'bg-white text-blue-700 shadow' 
        : 'text-white hover:bg-blue-500 hover:bg-opacity-75'
    }`;


  return (
    <div className="bg-gray-100 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 w-full min-h-screen flex flex-col">
      <nav className="bg-blue-600 dark:bg-blue-800 shadow-lg w-full">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
                <div className="flex items-center">
                    <div className="flex-shrink-0 text-white font-bold text-xl">
                        SAMI Plataforma
                    </div>
                </div>
                <div className="flex items-center">
                    <div className="flex items-baseline space-x-4">
                        <button className={navButtonClasses('accounting')} onClick={() => setCurrentView('accounting')}>
                            Módulo Contable
                        </button>
                         <button className={navButtonClasses('credit')} onClick={() => setCurrentView('credit')}>
                            Marketplace Créditos
                        </button>
                        <button className={navButtonClasses('education')} onClick={() => setCurrentView('education')}>
                            Academia SAMI
                        </button>
                        <button className={navButtonClasses('chat')} onClick={() => setCurrentView('chat')}>
                            Asistente AI
                        </button>
                    </div>
                </div>
            </div>
        </div>
      </nav>

      <main className="flex-grow w-full">
        {currentView === 'chat' && (
           <div className="w-full h-[calc(100vh-64px)] flex items-center justify-center p-4">
              <ChatWindow
                  messages={messages}
                  isLoading={isChatLoading}
                  onSendMessage={handleSendMessage}
                  error={chatError}
              />
           </div>
        )}
        {currentView === 'accounting' && (
          <AccountingModule 
            sales={sales}
            purchases={purchases}
            onAddInvoice={handleAddInvoice}
          />
        )}
        {currentView === 'credit' && (
            <CreditMarketplace salesHistory={sales} />
        )}
        {currentView === 'education' && (
            <EducationModule salesHistory={sales} />
        )}
      </main>
    </div>
  );
};

