export const getUserProgress = (): Promise<UserProgress> => {
    return Promise.resolve(userProgressData);
}

/**
 * Recommends courses based on user's financial health.
 * This acts as the backend recommendation engine.
 * @param salesHistory The user's sales invoices.
 * @returns An array of recommended Course objects.
 */
export const getRecommendedCourses = (salesHistory: Invoice[]): Course[] => {
    const samiScore = calculateSamiScore(salesHistory);
    const recommendations: Course[] = [];

    if (!samiScore) {
        // If no score, recommend the basics
        const basicCourse = allCourses.find(c => c.id === 'C04');
        if (basicCourse) recommendations.push(basicCourse);
        return recommendations;
    }

    // Rule 1: Low stability score -> Recommend Treasury Management
    if (samiScore.analysis.stability < 50) {
        const course = allCourses.find(c => c.id === 'C01');
        if (course) recommendations.push(course);
    }

    // Rule 2: Low growth score -> Recommend Digital Sales
    if (samiScore.analysis.growth < 50) {
        const course = allCourses.find(c => c.id === 'C02');
        if (course) recommendations.push(course);
    }

    // Rule 3: Low formality score -> Recommend Formalization
    if (samiScore.analysis.formality < 60) {
        const course = allCourses.find(c => c.id === 'C03');
        if (course) recommendations.push(course);
    }

    // If no specific recommendations, suggest the basics
    if (recommendations.length === 0) {
        const course = allCourses.find(c => c.id === 'C04');
        if (course) recommendations.push(course);
    }

    return recommendations;
};

import React, { useState, useEffect } from 'react';
import type { Course, Invoice, UserProgress } from '../types';
import { getCourses, getUserProgress, getRecommendedCourses } from '../services/educationService';
