interface EducationModuleProps {
  salesHistory: Invoice[];
}

const EducationModule: React.FC<EducationModuleProps> = ({ salesHistory }) => {
  const [courses, setCourses] = useState<Course[]>([]);
  const [recommendedCourses, setRecommendedCourses] = useState<Course[]>([]);
  const [userProgress, setUserProgress] = useState<UserProgress>({});
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const [allCourses, progress] = await Promise.all([
          getCourses(),
          getUserProgress(),
        ]);

        const recommendations = getRecommendedCourses(salesHistory);

        setCourses(allCourses);
        setRecommendedCourses(recommendations);
        setUserProgress(progress);
      } catch (error) {
        console.error("Failed to load education data:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [salesHistory]);

  const calculateProgress = (course: Course): number => {
    const completedLessons = course.lessons.filter(lesson => userProgress[lesson.id]).length;
    return (completedLessons / course.lessons.length) * 100;
