                isRecommended={true}
              />
            ))}
          </div>
        ) : (
          <p className="text-gray-500 dark:text-gray-400">No hay recomendaciones por ahora. ¡Explora nuestros cursos!</p>
        )}
      </section>

      {/* All Courses Section */}
      <section>
        <h2 className="text-2xl font-bold text-gray-800 dark:text-white mb-4">Todos los Cursos</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
