  isFinanceCertified: boolean;
}

const EducationModule: React.FC<EducationModuleProps> = ({ salesHistory, courses, userProgress, onLessonComplete, isFinanceCertified }) => {
  const [recommendedCourses, setRecommendedCourses] = useState<Course[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [selectedCourse, setSelectedCourse] = useState<Course | null>(null);

  useEffect(() => {
    setIsLoading(true);
    const recommendations = getRecommendedCourses(salesHistory);
    setRecommendedCourses(recommendations);
    setIsLoading(false);
  }, [salesHistory, courses]);

  const calculateProgress = (course: Course): number => {
    if (course.lessons.length === 0) return 0;
    const completedLessons = course.lessons.filter(lesson => userProgress[lesson.id]).length;
