  return (
    <>
      <div className="container mx-auto p-4 max-w-7xl h-full flex flex-col gap-8">
        <header>
          <h1 className="text-3xl font-bold text-gray-800 dark:text-white">Academia SAMI</h1>
          <p className="text-gray-600 dark:text-gray-400">Capacítate para llevar tu negocio al siguiente nivel. Completa cursos y obtén insignias.</p>
