import React, { useState } from 'react';
import type { Course, Lesson, UserProgress, QuizQuestion } from '../types';

interface LessonModalProps {
  course: Course;
  userProgress: UserProgress;
  onClose: () => void;
  onLessonComplete: (lessonId: string) => void;
}

const QuizView: React.FC<{
  quiz: QuizQuestion[];
  lessonId: string;
  onQuizComplete: (lessonId: string) => void;
}> = ({ quiz, lessonId, onQuizComplete }) => {
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [selectedAnswer, setSelectedAnswer] = useState<number | null>(null);
  const [showResult, setShowResult] = useState(false);

  const question = quiz[currentQuestionIndex];
  const isCorrect = selectedAnswer === question.correctAnswerIndex;

  const handleAnswer = () => {
    if (selectedAnswer === null) return;
    setShowResult(true);
  };

  const handleNext = () => {
    setShowResult(false);
    setSelectedAnswer(null);
    if (currentQuestionIndex < quiz.length - 1) {
      setCurrentQuestionIndex(currentQuestionIndex + 1);
    } else {
      onQuizComplete(lessonId);
    }
  };

  const getButtonClass = (index: number) => {
    if (!showResult) {
      return selectedAnswer === index 
        ? 'bg-blue-200 dark:bg-blue-800 border-blue-500' 
        : 'bg-white dark:bg-gray-700 hover:bg-gray-100 dark:hover:bg-gray-600';
    }
    if (index === question.correctAnswerIndex) {
      return 'bg-green-200 dark:bg-green-800 border-green-500';
    }
    if (index === selectedAnswer && !isCorrect) {
        return 'bg-red-200 dark:bg-red-800 border-red-500';
    }
    return 'bg-white dark:bg-gray-700';
  }

  return (
    <div className="mt-4 pt-4 border-t dark:border-gray-600">
      <h4 className="font-bold text-lg mb-2">Comprueba tu aprendizaje</h4>
      <p className="text-gray-800 dark:text-gray-200 mb-4">{question.question}</p>
      <div className="space-y-3 mb-4">
        {question.options.map((option, index) => (
            <button key={index} onClick={() => !showResult && setSelectedAnswer(index)} disabled={showResult}
                    className={`w-full text-left p-3 rounded-lg border-2 transition-colors ${getButtonClass(index)}`}>
                {option}
            </button>
        ))}
      </div>
      {showResult && (
        <div className={`p-3 rounded-lg mb-4 ${isCorrect ? 'bg-green-100 dark:bg-green-900' : 'bg-red-100 dark:bg-red-900'}`}>
            <p className={`font-bold ${isCorrect ? 'text-green-800 dark:text-green-200' : 'text-red-800 dark:text-red-200'}`}>
                {isCorrect ? '¡Correcto!' : 'Respuesta incorrecta.'}
            </p>
            <p className="text-sm text-gray-700 dark:text-gray-300 mt-1">{question.explanation}</p>
        </div>
      )}
      <div className="text-right">
        {!showResult ? (
          <button onClick={handleAnswer} disabled={selectedAnswer === null} className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-blue-400">
            Responder
          </button>
        ) : (
          <button onClick={handleNext} className="px-6 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700">
            {currentQuestionIndex < quiz.length - 1 ? 'Siguiente Pregunta' : 'Finalizar y Completar'}
          </button>
        )}
      </div>
    </div>
  )
}

