  const [courses, setCourses] = useState<Course[]>([]);
  const [userProgress, setUserProgress] = useState<UserProgress>({});

  useEffect(() => {
    // Fetch initial education data
    const fetchEducationData = async () => {
        const [allCourses, progress] = await Promise.all([getCourses(), getUserProgress()]);
        setCourses(allCourses);
        setUserProgress(progress);
    };
    fetchEducationData();
  }, []);

  const isFinanceCertified = useMemo(() => {
    const financeCourses = courses.filter(c => c.category === 'finance');
    if (financeCourses.length === 0) return false;

    return financeCourses.every(course => {
        const completedLessons = course.lessons.filter(lesson => userProgress[lesson.id]).length;
        return completedLessons === course.lessons.length;
    });
  }, [courses, userProgress]);

  const handleLessonComplete = (lessonId: string) => {
    setUserProgress(prev => ({ ...prev, [lessonId]: true }));
  };

  const handleAddInvoice = (invoice: Omit<Invoice, 'id'>) => {
      calculateTaxes([], [ { ...invoice, id: 'temp' } ]); 
      const newInvoice: Invoice = { ...invoice, id: crypto.randomUUID() };
      if (invoice.type === InvoiceType.SALE) {
          setSales(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      } else {
          setPurchases(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      }
  };

  useEffect(() => {
    setMessages([
      {
        id: 'initial',
        text: '¡Hola! Soy SAMI, tu asistente de IA. Estoy aquí para ayudarte con tus consultas sobre contabilidad, microcréditos y educación empresarial para MYPES en Perú. ¿En qué puedo ayudarte hoy?',
        sender: Sender.BOT,
      },
    ]);
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;
    const userMessage: Message = { id: Date.now().toString(), text, sender: Sender.USER };
    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setIsChatLoading(true);
    setChatError(null);
    try {
      const { chat, response } = await sendMessageToGemini(text, chatRef.current);
      chatRef.current = chat;
      const botMessage: Message = { id: Date.now().toString() + '-bot', text: response, sender: Sender.BOT };
      setMessages((prevMessages) => [...prevMessages, botMessage]);
    } catch (err) {
      const errorMessage = 'Lo siento, ocurrió un error al procesar tu solicitud. Por favor, inténtalo de nuevo más tarde.';
      setChatError(errorMessage);
      const errorBotMessage: Message = { id: Date.now().toString() + '-error', text: errorMessage, sender: Sender.BOT };
      setMessages((prevMessages) => [...prevMessages, errorBotMessage]);
      console.error(err);
    } finally {
      setIsChatLoading(false);
    }
  }, []);

  const navButtonClasses = (view: View) => 
    `px-4 py-2 text-sm font-medium rounded-md transition-colors ${
      currentView === view 
        ? 'bg-white text-blue-700 shadow' 
        : 'text-white hover:bg-blue-500 hover:bg-opacity-75'
    }`;

  const adminButtonClasses = (view: View) => 
    `px-3 py-1 text-xs font-medium rounded-md transition-colors ${
      currentView === view
      ? 'bg-yellow-300 text-yellow-900 shadow'
      : 'text-white bg-yellow-500 hover:bg-yellow-400'
    }`;

  return (
    <div className="bg-gray-100 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 w-full min-h-screen flex flex-col">
      <nav className="bg-blue-600 dark:bg-blue-800 shadow-lg w-full">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
                <div className="flex items-center">
                    <div className="flex-shrink-0 text-white font-bold text-xl">SAMI Plataforma</div>
                </div>
                <div className="flex items-center space-x-4">
                    <div className="hidden md:flex items-baseline space-x-4">
                      <button className={navButtonClasses('dashboard')} onClick={() => setCurrentView('dashboard')}>Dashboard</button>
                      <button className={navButtonClasses('accounting')} onClick={() => setCurrentView('accounting')}>Módulo Contable</button>
                      <button className={navButtonClasses('credit')} onClick={() => setCurrentView('credit')}>Marketplace Créditos</button>
                      <button className={navButtonClasses('education')} onClick={() => setCurrentView('education')}>Academia SAMI</button>
                      <button className={navButtonClasses('chat')} onClick={() => setCurrentView('chat')}>Asistente AI</button>
                    </div>
                    <button className={adminButtonClasses('admin')} onClick={() => setCurrentView('admin')}>Admin</button>
                </div>
            </div>
        </div>
      </nav>

      <main className="flex-grow w-full">
        {currentView === 'dashboard' && ( <Dashboard sales={sales} purchases={purchases} /> )}
        {currentView === 'chat' && (
           <div className="w-full h-[calc(100vh-64px)] flex items-center justify-center p-4">
              <ChatWindow messages={messages} isLoading={isChatLoading} onSendMessage={handleSendMessage} error={chatError} />
           </div>
        )}
        {currentView === 'accounting' && ( <AccountingModule sales={sales} purchases={purchases} onAddInvoice={handleAddInvoice} /> )}
        {currentView === 'credit' && ( <CreditMarketplace salesHistory={sales} isFinanceCertified={isFinanceCertified} /> )}
        {currentView === 'education' && (
            <EducationModule 
              salesHistory={sales} 
              courses={courses} 
              userProgress={userProgress}
              onLessonComplete={handleLessonComplete}
              isFinanceCertified={isFinanceCertified}
            />
        )}
        {currentView === 'admin' && ( <AdminDashboard /> )}
      </main>
    </div>
  );
};

export default App;

export enum Sender {
  USER = 'user',
  BOT = 'bot',
}

export interface Message {
  id: string;
  text: string;
  sender: Sender;
}

// --- Accounting Module Types ---

export enum InvoiceType {
  SALE = 'sale',
  PURCHASE = 'purchase',
}

export enum DocumentType {
  FACTURA = 'FACTURA',
  BOLETA = 'BOLETA_DE_VENTA',
}

export interface Invoice {
  id: string;
  type: InvoiceType;
  documentType: DocumentType;
  series: string;
  correlative: number;
  issueDate: string; // YYYY-MM-DD
  ruc?: string; // Optional for Boletas
  totalAmount: number;
}

export interface TaxSummary {
  totalSales: number;
  totalPurchases: number;
  igvDebit: number; // Débito fiscal (from sales)
  igvCredit: number; // Crédito fiscal (from purchases)
  igvPayable: number; // IGV a pagar
  incomeTaxAdvance: number; // Pago a cuenta de Impuesto a la Renta
}


// --- Credit Marketplace Module Types ---

export interface SamiScoreResult {
    score: number; // e.g., 300-850
    tier: 'Excelente' | 'Bueno' | 'Regular' | 'Necesita Mejora';
    analysis: {
        stability: number; // 0-100
        growth: number; // 0-100
        formality: number; // 0-100
    };
    avgMonthlySales: number;
}

export interface LoanOffer {
    partner: PartnerFinancialInstitution;
    maxAmount: number;
    monthlyInterestRate: number; // e.g., 0.03 for 3%
    termInMonths: number;
}

export interface PartnerFinancialInstitution {
    id: string;
    name: string;
    logoUrl: string;
}

// --- Education Module (SAMI Academy) Types ---

export type LessonType = 'video' | 'text';

export interface QuizQuestion {
  question: string;
  options: string[];
  correctAnswerIndex: number;
  explanation: string;
}

export interface Lesson {
  id: string;
  title: string;
  type: LessonType;
  content: string; // Markdown content
