import React from 'react';

interface KpiCardProps {
    title: string;
    value: string;
    trend: number;
    tooltip: string;
    isTrendPositive?: boolean; // Default true (higher is better)
}

const KpiCard: React.FC<KpiCardProps> = ({ title, value, trend, tooltip, isTrendPositive = true }) => {
    const isPositive = isTrendPositive ? trend > 0 : trend < 0;
    const isNegative = isTrendPositive ? trend < 0 : trend > 0;

    const trendColor = isPositive ? 'text-green-500' : isNegative ? 'text-red-500' : 'text-gray-500';

    const TrendArrow = () => {
        if (trend > 0) return <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 17a.75.75 0 01-.75-.75V5.612L5.03 9.77a.75.75 0 01-1.06-1.06l5.25-5.25a.75.75 0 011.06 0l5.25 5.25a.75.75 0 11-1.06 1.06L10.75 5.612V16.25A.75.75 0 0110 17z" clipRule="evenodd"></path></svg>;
        if (trend < 0) return <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 3a.75.75 0 01.75.75v10.638l4.22-4.158a.75.75 0 111.06 1.06l-5.25 5.25a.75.75 0 01-1.06 0l-5.25-5.25a.75.75 0 111.06-1.06L9.25 14.388V3.75A.75.75 0 0110 3z" clipRule="evenodd"></path></svg>;
        return null;
    }

    return (
        <div className="bg-white dark:bg-gray-800 p-4 rounded-lg shadow-md flex flex-col">
            <div className="flex justify-between items-center text-sm font-medium text-gray-500 dark:text-gray-400">
                <span>{title}</span>
                <div className="group relative">
                    <svg className="w-4 h-4 cursor-pointer" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd"></path></svg>
                    <div className="absolute bottom-full mb-2 w-48 bg-gray-700 text-white text-xs rounded py-1 px-2 opacity-0 group-hover:opacity-100 transition-opacity duration-300 z-10">
                        {tooltip}
                    </div>
                </div>
            </div>
            <div className="mt-2 flex-grow flex items-end justify-between">
                <p className="text-3xl font-bold text-gray-900 dark:text-white">{value}</p>
                <div className={`flex items-center text-sm font-semibold ${trendColor}`}>
                    <TrendArrow />
                    <span>{(Math.abs(trend) * 100).toFixed(1)}%</span>
                </div>
            </div>
        </div>
    );
};

export default KpiCard;

