                    onChange={e => setCurrentUser(mockUsers.find(u => u.id === e.target.value)!)}
                    className="bg-blue-500 border-none rounded-md text-xs py-0.5 px-2 focus:ring-0"
                >
                    <option value="u1">Fundador (Admin)</option>
                    <option value="u2">Asistente</option>
                </select>
            </div>
        </div>
      </nav>

      <main className="flex-grow w-full">
        {currentView === 'dashboard' && ( <Dashboard sales={sales} purchases={purchases} /> )}
        {currentView === 'chat' && (
           <div className="w-full h-[calc(100vh-80px)] flex items-center justify-center p-4">
              <ChatWindow messages={messages} isLoading={isChatLoading} onSendMessage={handleSendMessage} error={chatError} />
           </div>
        )}
        {currentView === 'accounting' && ( <AccountingModule sales={sales} purchases={purchases} onAddInvoice={handleAddInvoice} /> )}
        {currentView === 'credit' && ( <CreditMarketplace salesHistory={sales} isFinanceCertified={isFinanceCertified} /> )}
        {currentView === 'education' && (
            <EducationModule 
              salesHistory={sales} 
              courses={courses} 
              userProgress={userProgress}
              onLessonComplete={handleLessonComplete}
              isFinanceCertified={isFinanceCertified}
            />
        )}
        {currentView === 'admin' && isAdminAuthenticated && ( <AdminDashboard currentUser={currentUser} /> )}
        {currentView === 'admin' && !isAdminAuthenticated && currentUser.role === 'admin' && (
          <div className="text-center p-8">
            <p className="text-red-500">Acceso no autorizado. Se requiere autenticación.</p>
          </div>
        )}
      </main>

      {is2faModalOpen && (
        <TwoFactorAuthModal 
            onClose={() => setIs2faModalOpen(false)}
            onSuccess={handle2faSuccess}
        />
      )}
    </div>
  );
};

