import type { User, AuditLog } from '../types';

// In a real application, this would be a secure, append-only database table.
// For this simulation, we use an in-memory array.
const auditLogStore: AuditLog[] = [];

/**
 * Logs a sensitive action performed by a user.
 * @param user The user performing the action.
 * @param action A description of the action.
 */
export const logAdminAction = (user: User, action: string): void => {
    const logEntry: AuditLog = {
        id: crypto.randomUUID(),
        timestamp: new Date().toISOString(),
        user: {
            id: user.id,
            name: user.name,
        },
        action: action,
    };

    // Simulate writing to a secure log
    console.log(`[AUDIT LOG] User: ${user.name} (${user.id}), Action: ${action}`);
    auditLogStore.unshift(logEntry); // Add to the top for easy viewing
};

/**
 * Retrieves the audit log. In a real system, this would be protected
 * and possibly paginated.
 * @returns A promise that resolves to an array of audit logs.
 */
export const getAuditLogs = async (): Promise<AuditLog[]> => {
    // Simulate network delay
    await new Promise(res => setTimeout(res, 200));
    return Promise.resolve([...auditLogStore]);
};

