import React, { useState, useRef, useEffect } from 'react';

interface TwoFactorAuthModalProps {
  onClose: () => void;
  onSuccess: () => void;
}

const CORRECT_CODE = '123456'; // Hardcoded for simulation

const TwoFactorAuthModal: React.FC<TwoFactorAuthModalProps> = ({ onClose, onSuccess }) => {
  const [code, setCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setIsLoading(true);

    // Simulate network verification
    setTimeout(() => {
        if (code === CORRECT_CODE) {
            onSuccess();
        } else {
            setError('Código incorrecto. Inténtalo de nuevo.');
            setCode('');
        }
        setIsLoading(false);
    }, 500);
  };

  return (
    <div 
        className="fixed inset-0 bg-black bg-opacity-70 flex items-center justify-center z-50 p-4"
        onClick={onClose}
    >
      <div 
        className="bg-white dark:bg-gray-800 rounded-lg shadow-2xl w-full max-w-sm p-6 text-center"
        onClick={e => e.stopPropagation()}
      >
        <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-2">Verificación de Dos Factores</h2>
        <p className="text-gray-600 dark:text-gray-400 mb-4">
          Ingresa el código de 6 dígitos de tu aplicación de autenticación. (Pista: es 123456)
        </p>

        <form onSubmit={handleSubmit}>
            <input
                ref={inputRef}
                type="text"
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
                maxLength={6}
                className="w-full p-3 text-center text-2xl tracking-[.5em] font-mono bg-gray-100 dark:bg-gray-700 border-2 border-gray-300 dark:border-gray-600 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="------"
                disabled={isLoading}
            />

            {error && <p className="text-red-500 text-sm mt-2">{error}</p>}

            <div className="mt-6 flex flex-col gap-2">
                <button
                    type="submit"
                    disabled={isLoading || code.length !== 6}
                    className="w-full bg-blue-600 text-white font-bold py-3 px-4 rounded-lg hover:bg-blue-700 disabled:bg-blue-400 transition-colors"
                >
                    {isLoading ? 'Verificando...' : 'Verificar Código'}
                </button>
                 <button
                    type="button"
                    onClick={onClose}
                    className="w-full text-gray-600 dark:text-gray-300 font-medium py-2 px-4 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-700 transition-colors"
                >
                    Cancelar
                </button>
            </div>
        </form>

      </div>
    </div>
  );
};

