import type { AdminDashboardData, PartnerPerformance } from '../types';

/**
 * Masks a Peruvian RUC number.
 * Keeps the first 4 and last 3 digits.
 * Example: 20601234567 -> 2060****567
 * @param ruc The RUC string to mask.
 * @returns The masked RUC string.
 */
export const maskRuc = (ruc: string): string => {
    if (!ruc || ruc.length !== 11) {
        return 'RUC_INVALIDO';
    }
    return `${ruc.substring(0, 4)}****${ruc.substring(8)}`;
};


/**
 * Masks a financial amount by applying a random deviation.
 * This makes the number inaccurate but keeps it in a plausible range for testing UI.
 * @param amount The original amount.
 * @returns A slightly modified amount.
 */
export const maskAmount = (amount: number): number => {
    const deviation = (Math.random() - 0.5) * 0.2; // +/- 10%
    const masked = amount * (1 + deviation);
    return parseFloat(masked.toFixed(2));
};


/**
 * Masks a partner name to a generic identifier.
 * @param name The original partner name.
 * @param id The partner's unique ID.
 * @returns A generic partner name.
 */
export const maskPartnerName = (id: string): string => {
    const hash = id.split('').reduce((acc, char) => acc + char.charCodeAt(0), 0);
    const letter = String.fromCharCode(65 + (hash % 26)); // A-Z
    return `Partner Financiero ${letter}`;
}

/**
 * Applies masking to the entire Admin KPI data object.
 * @param data The real AdminDashboardData object.
 * @returns A new object with masked values.
 */
export const maskAdminKpis = (data: AdminDashboardData): AdminDashboardData => ({
    ...data,
    mrr: {
        ...data.mrr,
        value: maskAmount(data.mrr.value)
    },
    churnRate: {
        ...data.churnRate,
        value: maskAmount(data.churnRate.value)
    }
});


/**
 * Applies masking to the Partner Performance data array.
 * @param data Array of real PartnerPerformance objects.
 * @returns A new array with masked partner data.
 */
export const maskPartnerPerformance = (data: PartnerPerformance[]): PartnerPerformance[] => {
    return data.map(p => ({
        ...p,
        partner: {
            ...p.partner,
            name: maskPartnerName(p.partner.id),
        },
        offersSent: Math.round(maskAmount(p.offersSent)),
        loansDisbursed: Math.round(maskAmount(p.loansDisbursed)),
    }));
};

// --- CISO NOTICE: SIMULATION ONLY ---
// This file simulates the client-side *concept* of interacting with an encryption service.
// In a real, secure application, the actual encryption and decryption MUST happen on the server-side.
// Plaintext data should never be sent to the client for encryption; it should be sent over TLS and
// encrypted by the backend before being stored.

/**
 * Simulates the encryption of data before it's sent to the server for storage.
 * In a real implementation, this function would not exist on the client.
 * The backend would receive data over TLS and use a library like `crypto` in Node.js
 * with AES-256-GCM to encrypt the data. The encryption key would be managed by a
 * secure Key Management Service (KMS) like AWS KMS or Google Cloud KMS.
 *
 * @param data The plaintext data (e.g., a user's RUC or an invoice amount).
 * @returns A string representing the encrypted data (in this simulation, it's a mock format).
 */
export const encryptData = <T>(data: T): string => {
    // In a real backend:
    // 1. Get a data encryption key (DEK) from the KMS.
    // 2. Use the DEK to encrypt the data using AES-256-GCM.
    // 3. Store the encrypted data along with the encrypted DEK.
    // 4. Return the encrypted blob.

    // Simulation:
    const dataString = JSON.stringify(data);
    // This is NOT real encryption. It's a placeholder to demonstrate the concept.
    const mockEncrypted = `enc-aes256-gcm(${btoa(dataString)})`;
    console.log(`[ENCRYPTION-SIM] Encrypting: ${dataString}. Result: ${mockEncrypted}`);
    return mockEncrypted;
};

/**
 * Simulates the decryption of data received from the server.
 * In a real implementation, this function would not exist on the client.
 * A protected API endpoint would receive a request, fetch the encrypted data,
 * ask the KMS to decrypt the data encryption key (DEK), use the plaintext DEK
 * to decrypt the data, and then return the plaintext data to the authorized client over TLS.
 *
 * @param encryptedData A string representing the encrypted data.
 * @returns The original plaintext data.
 */
export const decryptData = <T>(encryptedData: string): T => {
    // In a real backend:
    // 1. Parse the encrypted blob to get encrypted data and the encrypted DEK.
    // 2. Send the encrypted DEK to the KMS to get the plaintext DEK.
    // 3. Use the plaintext DEK to decrypt the data using AES-256-GCM.
    // 4. Return the plaintext data.

    // Simulation:
    try {
        const base64Part = encryptedData.match(/enc-aes256-gcm\(([^)]+)\)/)?.[1];
        if (!base64Part) throw new Error("Invalid mock encrypted format");
        const decryptedString = atob(base64Part);
        console.log(`[ENCRYPTION-SIM] Decrypting: ${encryptedData}. Result: ${decryptedString}`);
        return JSON.parse(decryptedString);
    } catch (e) {
        console.error("Mock decryption failed", e);
        throw new Error("Decryption failed");
    }
};

