import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import type { Message, Invoice, UserProgress, Course } from './types';
import { Sender, InvoiceType } from './types';
import ChatWindow from './components/ChatWindow';
import AccountingModule from './components/AccountingModule';
import CreditMarketplace from './components/CreditMarketplace';
import EducationModule from './components/EducationModule';
import Dashboard from './components/Dashboard';
import AdminDashboard from './components/AdminDashboard';
import TwoFactorAuthModal from './components/TwoFactorAuthModal';
import { sendMessageToGemini } from './services/geminiService';
import { calculateTaxes } from './services/accountingService';
import { getCourses, getUserProgress } from './services/educationService';
import { logAdminAction } from './services/auditService';
import type { Chat } from '@google/genai';
import { useAuth } from './context/AuthContext';

type View = 'dashboard' | 'chat' | 'accounting' | 'credit' | 'education' | 'admin';

const App: React.FC = () => {
  const { currentUser, logout } = useAuth();
  const [currentView, setCurrentView] = useState<View>('dashboard');

  // Security State
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(currentUser?.role !== 'admin');
  const [is2faModalOpen, setIs2faModalOpen] = useState(false);

  // Chatbot State
  const [messages, setMessages] = useState<Message[]>([]);
  const [isChatLoading, setIsChatLoading] = useState<boolean>(false);
  const [chatError, setChatError] = useState<string | null>(null);
  const chatRef = useRef<Chat | null>(null);

  // Accounting & Credit State
  const [sales, setSales] = useState<Invoice[]>([]);
  const [purchases, setPurchases] = useState<Invoice[]>([]);

  // Education State
  const [courses, setCourses] = useState<Course[]>([]);
  const [userProgress, setUserProgress] = useState<UserProgress>({});

  useEffect(() => {
    if (currentUser?.role === 'admin') {
      setCurrentView('admin');
      handleAdminAccess(); // Trigger 2FA check on initial load for admin
    } else {
      setCurrentView('dashboard');
    }
  }, [currentUser]);

  useEffect(() => {
    // Fetch initial education data
    const fetchEducationData = async () => {
        const [allCourses, progress] = await Promise.all([getCourses(), getUserProgress()]);
        setCourses(allCourses);
        setUserProgress(progress);
    };
    fetchEducationData();
  }, []);

  const isFinanceCertified = useMemo(() => {
    const financeCourses = courses.filter(c => c.category === 'finance');
    if (financeCourses.length === 0) return false;

    return financeCourses.every(course => {
        const completedLessons = course.lessons.filter(lesson => userProgress[lesson.id]).length;
        return completedLessons === course.lessons.length;
    });
  }, [courses, userProgress]);

  const handleLessonComplete = (lessonId: string) => {
    setUserProgress(prev => ({ ...prev, [lessonId]: true }));
  };

  const handleAddInvoice = (invoice: Omit<Invoice, 'id'>) => {
      calculateTaxes([], [ { ...invoice, id: 'temp' } ]); 
      const newInvoice: Invoice = { ...invoice, id: crypto.randomUUID() };
      if (invoice.type === InvoiceType.SALE) {
          setSales(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      } else {
          setPurchases(prev => [...prev, newInvoice].sort((a,b) => Date.parse(b.issueDate) - Date.parse(a.issueDate)));
      }
  };

  useEffect(() => {
    setMessages([
      {
        id: 'initial',
        text: '¡Hola! Soy SAMI, tu asistente de IA. Estoy aquí para ayudarte con tus consultas sobre contabilidad, microcréditos y educación empresarial para MYPES en Perú. ¿En qué puedo ayudarte hoy?',
        sender: Sender.BOT,
      },
    ]);
  }, []);

  const handleSendMessage = useCallback(async (text: string) => {
    if (!text.trim()) return;
    const userMessage: Message = { id: Date.now().toString(), text, sender: Sender.USER };
    setMessages((prevMessages) => [...prevMessages, userMessage]);
    setIsChatLoading(true);
    setChatError(null);
    try {
      const { chat, response } = await sendMessageToGemini(text, chatRef.current);
      chatRef.current = chat;
      const botMessage: Message = { id: Date.now().toString() + '-bot', text: response, sender: Sender.BOT };
      setMessages((prevMessages) => [...prevMessages, botMessage]);
    } catch (err) {
      const errorMessage = 'Lo siento, ocurrió un error al procesar tu solicitud. Por favor, inténtalo de nuevo más tarde.';
      setChatError(errorMessage);
      const errorBotMessage: Message = { id: Date.now().toString() + '-error', text: errorMessage, sender: Sender.BOT };
      setMessages((prevMessages) => [...prevMessages, errorBotMessage]);
      console.error(err);
    } finally {
      setIsChatLoading(false);
    }
  }, []);

  const handleAdminAccess = () => {
    if (currentUser?.role === 'admin' && !isAdminAuthenticated) {
      setIs2faModalOpen(true);
    } else if (currentUser?.role === 'admin') {
      setCurrentView('admin');
    }
  };

  const handle2faSuccess = () => {
    if(!currentUser) return;
    logAdminAction(currentUser, 'Inicio de sesión de administrador exitoso (2FA verificado)');
    setIsAdminAuthenticated(true);
    setIs2faModalOpen(false);
    setCurrentView('admin');
  };

  const navButtonClasses = (view: View) => 
    `px-4 py-2 text-sm font-medium rounded-md transition-colors ${
      currentView === view 
        ? 'bg-white text-blue-700 shadow' 
        : 'text-white hover:bg-blue-500 hover:bg-opacity-75'
    }`;

  const adminButtonClasses = () => 
    `px-3 py-1 text-xs font-medium rounded-md transition-colors ${
      currentView === 'admin'
      ? 'bg-yellow-300 text-yellow-900 shadow'
      : 'text-white bg-yellow-500 hover:bg-yellow-400'
    }`;

  if (!currentUser) {
    return null; // Should be redirected by router
  }

  return (
    <div className="bg-gray-100 dark:bg-gray-900 font-sans text-gray-900 dark:text-gray-100 w-full min-h-screen flex flex-col">
      <nav className="bg-blue-600 dark:bg-blue-800 shadow-lg w-full">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex items-center justify-between h-16">
                <div className="flex items-center">
                    <div className="flex-shrink-0 text-white font-bold text-xl">SAMI Plataforma</div>
                </div>
                <div className="flex items-center space-x-4">
                    <div className="hidden md:flex items-baseline space-x-4">
                      <button className={navButtonClasses('dashboard')} onClick={() => setCurrentView('dashboard')}>Dashboard</button>
                      <button className={navButtonClasses('accounting')} onClick={() => setCurrentView('accounting')}>Contabilidad</button>
                      <button className={navButtonClasses('credit')} onClick={() => setCurrentView('credit')}>Créditos</button>
                      <button className={navButtonClasses('education')} onClick={() => setCurrentView('education')}>Academia</button>
                      <button className={navButtonClasses('chat')} onClick={() => setCurrentView('chat')}>Asistente AI</button>
                    </div>
                    <div className="flex items-center space-x-3">
                        {currentUser.role === 'admin' && (
                          <button className={adminButtonClasses()} onClick={handleAdminAccess}>Admin</button>
                        )}
                        <button onClick={logout} className="text-white text-sm hover:underline">Salir</button>
                    </div>
                </div>
            </div>
        </div>
      </nav>

      <main className="flex-grow w-full">
        {currentView === 'dashboard' && currentUser.role === 'user' && ( <Dashboard sales={sales} purchases={purchases} /> )}
        {currentView === 'chat' && (
           <div className="w-full h-[calc(100vh-64px)] flex items-center justify-center p-4">
              <ChatWindow messages={messages} isLoading={isChatLoading} onSendMessage={handleSendMessage} error={chatError} />
           </div>
        )}
        {currentView === 'accounting' && ( <AccountingModule sales={sales} purchases={purchases} onAddInvoice={handleAddInvoice} /> )}
        {currentView === 'credit' && ( <CreditMarketplace salesHistory={sales} isFinanceCertified={isFinanceCertified} /> )}
        {currentView === 'education' && (
            <EducationModule 
              salesHistory={sales} 
              courses={courses} 
              userProgress={userProgress}
              onLessonComplete={handleLessonComplete}
              isFinanceCertified={isFinanceCertified}
            />
        )}
        {currentView === 'admin' && isAdminAuthenticated && currentUser.role === 'admin' && ( <AdminDashboard currentUser={currentUser} /> )}

        {/* Fallback/Unauthorized views */}
        {currentView === 'admin' && (!isAdminAuthenticated || currentUser.role !== 'admin') && (
          <div className="text-center p-8">
            <p className="text-red-500">Acceso no autorizado. Se requiere autenticación de administrador.</p>
          </div>
        )}
         {currentView === 'dashboard' && currentUser.role !== 'user' && (
          <div className="text-center p-8">
            <p className="text-gray-500">Los administradores no tienen un dashboard de emprendedor. Por favor, acceda a la sección de Admin.</p>
          </div>
        )}
      </main>

      {is2faModalOpen && (
        <TwoFactorAuthModal 
            onClose={() => setIs2faModalOpen(false)}
            onSuccess={handle2faSuccess}
        />
      )}
    </div>
  );
};

