import React, { useState } from 'react';
import { useAuth } from './context/AuthContext';
import App from './App';
import LandingPage from './components/LandingPage';
import Login from './components/Login';

type Route = 'landing' | 'login' | 'app';

const SamiRouter: React.FC = () => {
  const { currentUser } = useAuth();
  const [route, setRoute] = useState<Route>(currentUser ? 'app' : 'landing');

  const navigateTo = (newRoute: Route) => {
    // Basic gatekeeping
    if (newRoute === 'app' && !currentUser) {
      setRoute('login');
    } else {
      setRoute(newRoute);
    }
  };

  if (currentUser) {
    return <App />;
  }

  switch(route) {
    case 'login':
      return <Login onLoginSuccess={() => navigateTo('app')} />;
    case 'landing':
    default:
      return <LandingPage onLoginClick={() => navigateTo('login')} />;
  }
};

export default SamiRouter;

import React, { createContext, useState, useContext, ReactNode } from 'react';
import type { User } from '../types';

interface AuthContextType {
  currentUser: User | null;
  login: (user: User) => void;
  logout: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const mockUsers: User[] = [
  { id: 'u1', name: 'Maria Rodriguez', role: 'admin' },
  { id: 'u2', name: 'Carlos Gomez', role: 'user' }
];

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  // In a real app, you'd check localStorage or a session cookie here
  const [currentUser, setCurrentUser] = useState<User | null>(null);

  const login = (user: User) => {
    // In a real app, this would involve an API call and setting a token
    const foundUser = mockUsers.find(u => u.role === user.role);
    if (foundUser) {
        setCurrentUser(foundUser);
    }
  };

  const logout = () => {
    // In a real app, this would clear the token and call a logout endpoint
    setCurrentUser(null);
  };

  return (
    <AuthContext.Provider value={{ currentUser, login, logout }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

import React, { useState, useMemo } from 'react';

const LoanSimulator: React.FC = () => {
    const [amount, setAmount] = useState(5000);
    const [ruc, setRuc] = useState('');
    const [submitted, setSubmitted] = useState(false);
    const minAmount = 1000;
    const maxAmount = 50000;

    const monthlyPayment = useMemo(() => {
        const principal = amount;
        const annualInterestRate = 0.45; // Simulated average TCEA
        const monthlyInterestRate = annualInterestRate / 12;
        const termInMonths = 12;

        if (monthlyInterestRate === 0) return principal / termInMonths;

        const monthly = principal * monthlyInterestRate * Math.pow(1 + monthlyInterestRate, termInMonths) / (Math.pow(1 + monthlyInterestRate, termInMonths) - 1);
        return monthly;
    }, [amount]);

    const handleRucSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        setSubmitted(true);
    };

    return (
        <div className="bg-white rounded-2xl shadow-2xl p-8 md:p-12 max-w-4xl mx-auto">
            <div className="grid md:grid-cols-2 gap-8 md:gap-12 items-center">
                <div className="text-center md:text-left">
                    <h2 className="text-3xl font-bold text-gray-900">Simula tu Préstamo para Capital de Trabajo</h2>
                    <p className="mt-2 text-gray-600">Descubre cuánto podrías recibir para impulsar tu negocio. ¡Sin compromiso!</p>
                    <img 
                        src="https://images.unsplash.com/photo-1620714223084-86c9df2a6881?q=80&w=1770&auto=format&fit=crop"
                        alt="Emprendedora peruana en su taller de confección en Gamarra, sonriendo con confianza."
                        className="mt-6 rounded-lg shadow-md object-cover w-full h-48"
                    />
                </div>
                <div>
                    <div className="mb-6">
                        <label htmlFor="amount" className="block text-lg font-semibold text-gray-700">Monto deseado:</label>
                        <p className="text-4xl font-bold text-blue-600 my-2">
                            S/ {amount.toLocaleString('es-PE')}
                        </p>
                        <input
                            id="amount"
                            type="range"
                            min={minAmount}
                            max={maxAmount}
                            step="500"
                            value={amount}
                            onChange={(e) => setAmount(Number(e.target.value))}
                            className="w-full h-3 bg-gray-200 rounded-lg appearance-none cursor-pointer range-lg dark:bg-gray-700"
                        />
                         <div className="flex justify-between text-sm text-gray-500 mt-1">
                            <span>S/ {minAmount.toLocaleString('es-PE')}</span>
                            <span>S/ {maxAmount.toLocaleString('es-PE')}</span>
                        </div>
                    </div>

                    <div className="bg-blue-50 border-l-4 border-blue-500 p-4 rounded-r-lg">
                        <p className="text-sm text-gray-600">Cuota mensual estimada a 12 meses:</p>
                        <p className="text-2xl font-bold text-gray-800">
                            S/ {monthlyPayment.toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                        </p>
                        <p className="text-xs text-gray-500 mt-1">*La tasa es referencial y se personaliza con tu RUC.</p>
                    </div>

                    {!submitted ? (
                        <form onSubmit={handleRucSubmit} className="mt-6">
                            <label htmlFor="ruc" className="block text-sm font-medium text-gray-700 mb-1">Ingresa tu RUC para personalizar tu tasa y continuar:</label>
                             <div className="flex gap-2">
                                <input
                                    id="ruc"
                                    type="text"
                                    value={ruc}
                                    onChange={(e) => setRuc(e.target.value.replace(/\D/g, ''))}
                                    maxLength={11}
                                    placeholder="RUC de tu negocio"
                                    required
                                    className="flex-grow p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                                />
                                <button type="submit" className="bg-green-500 text-white font-bold py-3 px-6 rounded-lg hover:bg-green-600 transition-colors">
                                    Evaluar
                                </button>
                            </div>
                        </form>
                    ) : (
                         <div className="mt-6 text-center bg-green-100 p-4 rounded-lg">
                            <p className="font-semibold text-green-800">¡Gracias! Un asesor se pondrá en contacto contigo.</p>
                            <p className="text-sm text-green-700">Para una evaluación completa, regístrate y conecta tus datos contables.</p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default LoanSimulator;

import React, { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import type { User } from '../types';

interface LoginProps {
  onLoginSuccess: () => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [role, setRole] = useState<'user' | 'admin'>('user');
  const [error, setError] = useState('');
  const { login } = useAuth();

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    try {
      // In a real app, you'd have username/password fields and an API call.
      // Here, we just log in with the selected role.
      const userToLogin: User = {
        id: role === 'admin' ? 'u1' : 'u2',
        name: role === 'admin' ? 'Maria Rodriguez' : 'Carlos Gomez',
        role: role,
      };
      login(userToLogin);
      onLoginSuccess();
    } catch (err) {
      setError('Failed to log in');
    }
  };

  return (
    <div className="bg-gray-100 min-h-screen flex items-center justify-center">
      <div className="w-full max-w-md bg-white rounded-lg shadow-xl p-8">
        <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-blue-600">SAMI</h1>
            <p className="text-gray-600">Bienvenido de vuelta a tu plataforma de gestión.</p>
        </div>

        <form onSubmit={handleLogin}>
          <div className="mb-6">
            <label htmlFor="role-select" className="block text-sm font-medium text-gray-700 mb-2">
              Selecciona tu perfil (Simulación):
            </label>
            <select 
              id="role-select"
              value={role}
              onChange={(e) => setRole(e.target.value as 'user' | 'admin')}
              className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
            >
              <option value="user">Emprendedor (Usuario)</option>
              <option value="admin">Fundador (Admin)</option>
            </select>
          </div>

          <div className="mb-6">
             <label htmlFor="password" className="block text-sm font-medium text-gray-700 mb-2">
              Contraseña
            </label>
            <input 
                type="password"
                id="password"
                defaultValue="supersecret"
                className="w-full p-3 border border-gray-300 rounded-lg bg-gray-100"
                disabled
            />
          </div>

          {error && <p className="text-red-500 text-sm mb-4">{error}</p>}

          <button 
            type="submit"
            className="w-full bg-blue-600 text-white font-bold py-3 px-4 rounded-lg hover:bg-blue-700 transition-colors"
          >
            Iniciar Sesión
          </button>
        </form>
      </div>
    </div>
  );
};

export default Login;
